import{_ as t,o as i,c as r,a5 as a}from"./chunks/framework.CslsFoWx.js";const s="/VendoraSystem-docs/captures/2026-10-30-imprimante-simulee/android-01-simulateur-ticket-de-test-imprime.png",n="/VendoraSystem-docs/captures/2026-10-30-imprimante-simulee/android-02-plus-de-papier-file-suspendue.png",o="/VendoraSystem-docs/captures/2026-10-30-imprimante-simulee/android-03-prete-file-videe-2-tickets.png",h=JSON.parse(`{"title":"Lot 2.17 — Imprimante simulée et états d'imprimante (spec 11 RG-HW-06), couche prête pour le matériel — 30/10/2026","description":"","frontmatter":{},"headers":[],"relativePath":"preuves/2026-10-30-imprimante-simulee.md","filePath":"generated/preuves/2026-10-30-imprimante-simulee.md","lastUpdated":null}`),p={name:"preuves/2026-10-30-imprimante-simulee.md"};function d(m,e,u,l,c,g){return i(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="lot-2-17-—-imprimante-simulee-et-etats-d-imprimante-spec-11-rg-hw-06-couche-prete-pour-le-materiel-—-30-10-2026" tabindex="-1">Lot 2.17 — Imprimante simulée et états d&#39;imprimante (spec 11 RG-HW-06), couche prête pour le matériel — 30/10/2026 <a class="header-anchor" href="#lot-2-17-—-imprimante-simulee-et-etats-d-imprimante-spec-11-rg-hw-06-couche-prete-pour-le-materiel-—-30-10-2026" aria-label="Permalink to &quot;Lot 2.17 — Imprimante simulée et états d&#39;imprimante (spec 11 RG-HW-06), couche prête pour le matériel — 30/10/2026&quot;">​</a></h1><p class="muted">Dossier <code>docs/captures/2026-10-30-imprimante-simulee</code> · 3 image(s) · 0 trace(s)</p><div><p>Émulateur Android (caisse), réglages « Imprimante ». Jusqu&#39;ici la file d&#39;impression ne connaissait que « envoyé » ou « échec » : sans papier, chaque ticket consommait ses tentatives puis passait FAILED. Désormais la file interroge l&#39;imprimante AVANT d&#39;envoyer (sonde <code>PrinterStatusProbe</code> : DLE EOT sur TCP, état piloté sur le simulateur) ; <strong>plus de papier</strong> et <strong>capot ouvert</strong> suspendent la file sans tentative, qui repart dans l&#39;ordre dès que l&#39;imprimante est prête. L&#39;imprimante <strong>simulée</strong> (adresse réservée <code>simulateur</code>) permet d&#39;exercer tout cela sans matériel ; le vrai matériel se branche derrière le même <code>PrinterDriverRegistry</code> (TCP aujourd&#39;hui, Bluetooth / USB demain).</p><table tabindex="0"><thead><tr><th>Capture</th><th>Ce qu&#39;il faut voir</th></tr></thead><tbody><tr><td><a href="/VendoraSystem-docs/captures/2026-10-30-imprimante-simulee/android-01-simulateur-ticket-de-test-imprime.png">android-01-simulateur-ticket-de-test-imprime.png</a></td><td>Adresse « simulateur » adoptée d&#39;un geste (bouton « Utiliser l&#39;imprimante simulée »), puces d&#39;état <strong>Prête / Papier bas / Plus de papier / Capot ouvert / Hors ligne</strong>, « Ticket de test » → <strong>1 ticket imprimé par le simulateur</strong> avec son texte (Magasin, Ticket de test, date, largeur 80 mm)</td></tr><tr><td><a href="/VendoraSystem-docs/captures/2026-10-30-imprimante-simulee/android-02-plus-de-papier-file-suspendue.png">android-02-plus-de-papier-file-suspendue.png</a></td><td>État <strong>Plus de papier</strong> puis ticket de test : « <strong>Plus de papier — file d&#39;impression suspendue — ticket conservé en file, imprimé dès que l&#39;imprimante est prête</strong> », compteur toujours à 0 (aucune tentative consommée)</td></tr><tr><td><a href="/VendoraSystem-docs/captures/2026-10-30-imprimante-simulee/android-03-prete-file-videe-2-tickets.png">android-03-prete-file-videe-2-tickets.png</a></td><td>Retour à <strong>Prête</strong> : la file se vide toute seule, <strong>2 tickets imprimés</strong>, dernier ticket affiché</td></tr></tbody></table><p>Configuration conservée au redémarrage de l&#39;app (table <code>printer_config</code>, comme une imprimante réelle). iOS : même section « Imprimante simulée » dans les réglages (bouton, sélecteur d&#39;état, compteur, dernier ticket) et bandeau « … · N ticket(s) en attente » sur la feuille de paiement — couvert par <code>ImprimanteSimuleeTests</code>.</p><h2 id="piege-rencontre" tabindex="-1">Piège rencontré <a class="header-anchor" href="#piege-rencontre" aria-label="Permalink to &quot;Piège rencontré&quot;">​</a></h2><p>Une file qui contenait d&#39;anciens jobs vers une autre adresse (imprimante réelle des lots précédents) : la première version n&#39;interrogeait que l&#39;imprimante du <strong>premier</strong> job, donc le simulateur sans papier recevait quand même un envoi (tentative consommée). Corrigé : état interrogé <strong>par imprimante visée</strong>, seuls les jobs de l&#39;imprimante suspendue attendent, les autres (bons cuisine…) continuent — test « file à plusieurs imprimantes ».</p></div><h2 id="galerie" tabindex="-1">Galerie <a class="header-anchor" href="#galerie" aria-label="Permalink to &quot;Galerie&quot;">​</a></h2><div class="proof-grid"><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-30-imprimante-simulee/android-01-simulateur-ticket-de-test-imprime.png" target="_blank"><img src="'+s+'" alt="android-01-simulateur-ticket-de-test-imprime.png" loading="lazy"></a><figcaption>android-01-simulateur-ticket-de-test-imprime.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-30-imprimante-simulee/android-02-plus-de-papier-file-suspendue.png" target="_blank"><img src="'+n+'" alt="android-02-plus-de-papier-file-suspendue.png" loading="lazy"></a><figcaption>android-02-plus-de-papier-file-suspendue.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-30-imprimante-simulee/android-03-prete-file-videe-2-tickets.png" target="_blank"><img src="'+o+'" alt="android-03-prete-file-videe-2-tickets.png" loading="lazy"></a><figcaption>android-03-prete-file-videe-2-tickets.png</figcaption></figure></div>',5)])])}const v=t(p,[["render",d]]);export{h as __pageData,v as default};
